mapper.select:
SELECT 
FROM application_operations o
JOIN users u ON u.id = o.updated_by
WHERE o.space_id = #{spaceId} AND o.event_id = #{eventId}
  AND o.application_id = #{applicationId}

mapper.update:
UPDATE application_operations
SET memo = #{memo}, version = version + 1, updated_by = #{updatedBy}, updated_at = #{updatedAt}
WHERE space_id = #{spaceId} AND event_id = #{eventId}
  AND application_id = #{applicationId} AND version = #{expectedVersion}
